<style>
.amp-shell{display:grid;gap:24px}.amp-header{display:flex;justify-content:space-between;gap:24px;align-items:flex-start}.amp-kicker{margin:0 0 8px;color:var(--accent);font-size:12px;font-weight:800;letter-spacing:.14em}.amp-lead{max-width:720px}.amp-status{display:inline-flex;padding:5px 10px;border-radius:999px;background:#e8f4f2;color:var(--accent-dark);font-size:12px;font-weight:800}.amp-status--draft{background:#fff3d5;color:#775300}.amp-periods,.amp-sections{display:grid;gap:14px}.amp-period{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:18px;align-items:center;padding:20px;border:1px solid var(--line);border-radius:10px;background:#fff}.amp-period h2,.amp-section h2,.amp-section h3{margin:0}.amp-period__meta{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.amp-section{padding:20px;border:1px solid var(--line);border-radius:10px;background:#fff}.amp-section--nested{margin-top:12px;background:#f7fafb}.amp-prose{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.9}.amp-form{display:grid;gap:22px}.amp-form fieldset{min-width:0;margin:0;padding:18px;border:1px solid var(--line);border-radius:8px}.amp-form legend{padding:0 8px;font-weight:800}.amp-form textarea{min-height:120px;resize:vertical}.amp-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.amp-check{display:flex;gap:9px;align-items:flex-start}.amp-check input{width:auto;margin-top:4px}.amp-table{width:100%;border-collapse:collapse}.amp-table th,.amp-table td{padding:11px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}.amp-table th{font-size:12px;color:var(--muted)}.amp-empty{padding:24px;border:1px dashed var(--line);border-radius:8px;color:var(--muted);text-align:center}.amp-review{border-left:4px solid var(--accent);padding-left:18px}.amp-warning{padding:14px;border:1px solid #e6c66a;border-radius:8px;background:#fff9e9;color:#664d00}.amp-code{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:12px;overflow-wrap:anywhere}.amp-field-list{display:grid;gap:14px}.amp-field-item{position:relative;display:grid;gap:12px;padding:16px;border:1px solid var(--line);border-radius:8px}.amp-field-item>.danger-outline{justify-self:end}@media(max-width:640px){.amp-header,.amp-period{grid-template-columns:1fr;display:grid}.amp-row{grid-template-columns:1fr}.amp-table{display:block;overflow-x:auto}.amp-header .actions{justify-content:flex-start}}
</style>
